head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.gIsurCd;
// js_team
// page 변수.

scwin.gParamObj = new Array(4);
scwin.gISUR_CD;
scwin.gCOM_NM;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.PanelToGroupBox(panel_7);
        $c.cm.PanelToGroupBox(panel_8);
        MxTab_1.setSelectedTabIndex("1");
        await scwin.setCode();

        // debug 용 콘트롤들 모두 숨기기.
        scwin.hideDebugCtrls();
        await scwin.init();
        $c.cm.fn_com_isur(txb_Tab1_IsurCd, txb_Tab1_ComNm);

        // 코스닥일때만 상장법인공개여부,SMS전송여부 보여준다. -> 이 화면은 코스닥만 사용!
        if (scwin.gDepCd.substring(0, 2) !== '34') {
            btn_monthly_notices.hide();
            label_18.hide();
            $c.cm.setColumnProp(grd_Tab1_List, 'SUBMIT_SYS_USE_YN', 'Show', false);
            $c.cm.setColumnProp(grd_Tab1_List, 'SMS_TRNSM_YN', 'Show', false);
        }
        /**
    	if(gLdMktTp != '2') {
    grd_Tab1_List.setColumnProp('SUBMIT_SYS_USE_YN','Show',false) ;
    grd_Tab1_List.setColumnProp('SMS_TRNSM_YN','Show',false) ;
    	}
         */
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    grd_Tab3_List.hide();
    panel_mkt.hide();
    panel_mkt2.hide();
    panel_mkt3.hide();
    panel_mkt4.hide();
    dts_Tab1_Emp.UseFilter = true;
    dts_Tab3_Emp.UseFilter = true;
    dts_Tab4_Emp.UseFilter = true;
    if (scwin.gLdMktTp === "9") {
        panel_mkt.show("");
        panel_mkt2.show("");
        panel_mkt3.show("");
        panel_mkt4.show("");
        rdo_Tab1_Market_Flag.setValue("2");
        rdo_Tab2_Market_Flag.setValue("2");
        rdo_Tab3_Market_Flag.setValue("2");
        rdo_Tab4_Market_Flag.setValue("2");
    } else {
        rdo_Tab1_Market_Flag.setValue(scwin.gLdMktTp);
        rdo_Tab2_Market_Flag.setValue(scwin.gLdMktTp);
        rdo_Tab3_Market_Flag.setValue(scwin.gLdMktTp);
        rdo_Tab4_Market_Flag.setValue(scwin.gLdMktTp);
    }

    // TAB1
    edt_Tab1_SDate.setValue($c.ut.cGetToday2());

    // setObjectValue(edt_Tab1_EDate, calcMonth(cGetToday2(), 1));    2009.08.28 하루만 조회되도록 변경
    edt_Tab1_EDate.setValue($c.ut.cGetToday2());
    cmb_Tab1_Dep.setValue(js_dep_cd);
    cmb_Tab1_Emp.setValue(js_emp_no);
    dts_Tab1_Emp.Filter();

    // TAB2
    $c.stf.panelMsg(panel_page_tab2_2, "시장안내공시");
    // setObjectValue(cmb_PeriodTp2, "1");
    edt_Tab2_SDate.setValue($c.ut.cGetToday2());

    // TAB3
    // 공시사유코드
    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_RSN",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_RSN=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_PeriodTp_Tab3.setValue("5");
    cmb_Tab3_Dep.setValue(js_dep_cd);
    cmb_Tab3_Emp.setValue(js_emp_no);
    dts_Tab3_Emp.Filter();

    // TAB4
    cmb_Tab4_Dep.setValue(js_dep_cd);
    cmb_Tab4_Emp.setValue(js_emp_no);
    edt_Tab4_SDate.setValue($c.ut.cGetToday2());
    edt_Tab4_EDate.setValue($c.ut.cGetToday2());
    dts_Tab4_Emp.Filter();

    // 디폴트 검색
    await scwin.search();
};

