 * @description 「마감처리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Act_onclick = async function() {
    try {
        const options = {
            id: "ULDSTF30000_POP",
            title: '일정마감처리',
            type: "browserPopup",
            width: "345px",
            height: "245px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup('/dsclmgt/ULDSTF30000_POP.gfm', options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30000.btn_Act_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab1_OnLoadCompleted
 * @description dts_Grid_Tab1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_tab1);
        let vTOTALCNT = dts_Grid_Tab1.getCellData(1, "TOTALCNT"); // 전체 건수
        let vNOT_CONFIRM_CNT = dts_Grid_Tab1.getCellData(1, "NOT_CONFIRM_CNT"); // 미확정
        let vCONFIRM_CNT = dts_Grid_Tab1.getCellData(1, "CONFIRM_CNT"); // 확정
        let vCHARGE_CNT = dts_Grid_Tab1.getCellData(1, "CHARGE_CNT"); // 확정(담당자확인대상)
        let vNO_EDIT_CNT = dts_Grid_Tab1.getCellData(1, "NO_EDIT_CNT"); // 확정(번복금지기간)

        let msg = "전체 : " + vTOTALCNT + " 건 (";
        msg += "미확정 <font color='red'>" + vNOT_CONFIRM_CNT + "건</font>, ";
        msg += "확정 " + vCONFIRM_CNT + "건, ";
        msg += "확정(담당자확인대상) " + vCHARGE_CNT + "건, ";
        //    msg += "확정(번복금지기간) " + vNO_EDIT_CNT + "건";
        msg += ") ";
        $c.stf.panelMsg(panel_page_tab1_2, msg);
        // grd_Tab1_List.AutoResizeAllCol(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30000.dts_Grid_Tab1_OnLoadCompleted" });
    }
};

