/**
 * @method
 * @name btn_Tab1_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Tab1_Excel_onclick = async function() {
    try {
        if (dts_Grid_Tab1.getRowCount() < 1) {
            await $c.win.alert("저장할 정보가 없습니다.");
