/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
        if (nIndex === 1) {
            // 첫번째 탭 클릭시
            await scwin.search();
        } else if (nIndex === 2) {
            // 두번째 탭 클릭시
            await scwin.dailySearch();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30000.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30000.MxDataSet_com_isur_OnFilter" });
    }
};

