/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let edt_FromDate_year = edt_Tab1_SDate.getValue().substr(0, 4);
    let edt_FromDate_month = edt_Tab1_SDate.getValue().substr(4, 2) - 1;
    let edt_FromDate_day = edt_Tab1_SDate.getValue().substr(6, 2);
    let edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    let edt_ToDate_year = edt_Tab1_EDate.getValue().substr(0, 4);
    let edt_ToDate_month = edt_Tab1_EDate.getValue().substr(4, 2) - 1;
    let edt_ToDate_day = edt_Tab1_EDate.getValue().substr(6, 2);
    let edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);

    // 1년 이상의 기간은 검색 할 수 없다
    let date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (date_result > 365) {
        await $c.win.alert("검색기간은 1년을 초과할 수 없습니다.");
        return;
    }
    const MKT_ID = rdo_Tab1_Market_Flag.getValue();
    let ISUR_CD = txb_Tab1_IsurCd.getValue();
    const COMNM = txb_Tab1_ComNm.getValue();
    let SDATE = edt_Tab1_SDate.getValue();
    let EDATE = edt_Tab1_EDate.getValue();
    let DEPCD = cmb_Tab1_Dep.getValue();
    let EMPNO = cmb_Tab1_Emp.getValue();
    const RPTCD = txb_Tab1_RptCd.getValue();
    const RPTNM = txb_Tab1_RptNm.getValue();
    const STATUSCD = cmb_Tab1_Status.getValue();
    const ACT_YN = chb_Tab1_Act_Yn.getValue();
    url += "&MKT_ID=" + MKT_ID;
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&DEPCD=" + DEPCD;
    url += "&EMPNO=" + EMPNO;
    url += "&TEAM_ID=" + js_team;
    url += "&RPTCD=" + RPTCD;
    url += "&STATUSCD=" + STATUSCD;
    url += "&ACT_YN=" + ACT_YN;
    url += "&SUBMIT_SYS_USE_YN=" + cmb_SUBMIT_SYS_USE_YN.getValue();
    url += "&SMS_TRNSM_YN=" + cmb_SMS_TRNSM_YN.getValue();
    url += "&SCREN_ID=" + 'ULDSTF30000.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // alert(encodeURI(url));
    const sbmOptions = {
        id : "sbm_dts_Grid_Tab1",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Grid_Tab1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

