/**
 * @method
 * @name listDisclosureReason
 * @description list Disclosure Reason 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDisclosureReason = async function() {
    let ISUR_CD = txb_ISUR_CD.getValue();
    let SDATE = edt_Tab3_SDate.getValue();
    let EDATE = edt_Tab3_EDate.getValue();
    if (SDATE > EDATE) {
        await $c.win.alert("검색시작일은 검색종료일보다 앞설 수 없습니다.");
        return;
    }
    let DEPCD = cmb_Tab3_Dep.getValue();
    let EMPNO = cmb_Tab3_Emp.getValue();
    const LIST_STAT = scwin.getChkValue(chb_LIST_STAT_CD);
    const STATUS = cmb_Tab3_Status.getValue();
    let RSN_CD = "";
    for (let i = 0; i < dts_RSN.getRowCount(); i++) {
        for (let j = 0; j < 5; j++) {
            let tmp = dts_RSN.getCellData(i, "CHK" + (j + 1));
            if (tmp === "T" || tmp === 1) {
                const tmp2 = dts_RSN.getCellData(i, "COL_CD" + (j + 1));
                RSN_CD += tmp2 + "|";
            }
        }
    }
    // 위치.크기 바꾸기.
    $c.stf.SetWindowPos(grd_Tab3_List, grd_RSN.style.top, grd_RSN.style.left, grd_RSN.getStyle("width"), grd_RSN.getStyle("height"));
    grd_RSN.hide();
    grd_Tab3_List.show("");
    url += "&MKT_ID=" + rdo_Tab3_Market_Flag.getValue();
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&DEPCD=" + DEPCD;
    url += "&EMPNO=" + EMPNO;
    url += "&TEAM_ID=" + js_team;
    url += "&STATUS=" + STATUS;
    url += "&LIST_STAT=" + LIST_STAT;
    url += "&RSN_CD=" + RSN_CD;
    url += "&SCREN_ID=" + 'ULDSTF30000.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // alert(encodeURI(url));
    const sbmOptions = {
        id : "sbm_dts_Grid_Tab3",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Grid_Tab3=body.content",
        isProcessMsg : false
    };

