 * @name checkTab1Cond
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkTab1Cond = async function() {
    // 일자 체크
    if (edt_Tab1_SDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab1_SDate.focus();
        return;
    }

    // 일자 체크
    if (edt_Tab1_EDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab1_EDate.focus();
        return;
    }
    await scwin.search();
};

