        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab4_SDate.focus();
        return;
    }

    // 일자 체크
    if (edt_Tab4_EDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab4_EDate.focus();
        return;
    }
    await scwin.dateSearch();
};

