/**
 * @method
 * @name readSchedule
 * @description read Schedule 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSchedule = async function(GridID, row, colid) {
    if (row < 1) return;
    const CMD = "R";
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    const DISCLS_SCHDL_ADM_DD = objDataID.getCellData(row, "DISCLS_SCHDL_ADM_DD");
    const BYDD_SEQ = objDataID.getCellData(row, "BYDD_SEQ");
    const USR_ID = objDataID.getCellData(row, "INTEG_USR_ID");
    const SCHDL_TP_CD = objDataID.getCellData(row, "SCHDL_TP_CD");
    if (colid === "CD_NM" || colid === "SCHDL_CONFRM_YN") {
        if (await scwin.setParam(CMD, DISCLS_SCHDL_ADM_DD, BYDD_SEQ, USR_ID)) // formal arguments

        {
            let winTitle = "일정조회";
            if (SCHDL_TP_CD === "5" || SCHDL_TP_CD === "6") {
                let url = "/dsclmgt/ULDSTF30012.gfm";
                await $c.frame.CreateFrame("ULDSTF30012", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
            } else {
                let url = "/dsclmgt/ULDSTF30001.gfm";
                await $c.frame.CreateFrame("ULDSTF30001", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
                // frame.CreateDialogFrame("child01", "/dsclmgt/ULDSTF30001.gfm", "일정조회", 10, 10, 10, 20, "window");

            }
        }
    } else if (colid === "DISCLS_TITLE") {
        let AcptNo = objDataID.getCellData(row, "ACPT_NO");
        await $c.stf.openDisclViewer(AcptNo, "R");
    } else if (colid === "COM_ABBRV") {
        scwin.gIsurCd = objDataID.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "SUBMIT_SYS_USE_YN" || colid === "SMS_TRNSM_YN") {
        let url = "/dsclmgt/ULDSTF30011.gfm";
        let winTitle = "상장법인공개목록";
        // frame.CreateFrame("ULDSTF30011", url , winTitle , 10, 10, 10, 20, "window", 0, 0, true);
        $c.frame.path("/top").WinOpen("ULDSTF30011", url, winTitle, 607, 480);
    }
};

/**
 * @method
 * @name setParam
 * @description paramObj Update
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name isEngChar
 * @description is Eng Char 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.isEngChar = function(str) {
    const re = /[^-a-z_A-Z]/; // 영문자가 아닌 게 있는 걸 찾아라.
    return !re.test(str);
};

/**
 * @method
 * @name hideGridCol
 * @description hide Grid Col 처리
 * @param {String} GridID GridID
 * @returns {void}
 * @hidden N
 */
scwin.hideGridCol = function(GridID) {
    const ColCnt = GridID.getTotalCol();
    for (let i = 0; i < ColCnt; i++) {
        const ColID = GridID.GetColumnID(i);
        const HeaderNm = GridID.GetHdrDispName(-3, ColID);
        if (scwin.isEngChar(HeaderNm)) {
            // 영문 컬럼이면 숨겨라.
            GridID.setColumnProp(ColID, "Show", false);
        }
    }
};

